const fs = require('fs');
const src = fs.readFileSync('<TMP>/check/inline.js', 'utf8');
const calls = {};
const gradient = { addColorStop() {} };
function makeCtx() {
  return new Proxy({}, {
    get(t, k) {
      if (k in t) return t[k];
      if (k === 'createRadialGradient' || k === 'createLinearGradient') return () => gradient;
      if (k === 'getContext') return undefined;
      calls[k] = (calls[k] || 0) + 1;
      return () => {};
    },
    set(t, k, v) { t[k] = v; return true; }
  });
}
function makeCanvas() { const c = makeCtx(); return { width: 0, height: 0, style: {}, getContext: () => c }; }
const canvas = makeCanvas();
const listeners = {};
let rafCb = null;
const win = {
  innerWidth: 1280, innerHeight: 800, devicePixelRatio: 2,
  addEventListener(type, fn) { (listeners[type] = listeners[type] || []).push(fn); },
  matchMedia(q) { return { matches: global.__reduce, addEventListener(_, fn) { this._fn = fn; } }; },
  requestAnimationFrame(cb) { rafCb = cb; return 1; },
  cancelAnimationFrame() { rafCb = null; },
};
const doc = {
  getElementById: () => canvas,
  createElement: () => makeCanvas(),
};
global.__reduce = process.argv[2] === 'reduce';
const sandbox = { window: win, document: doc, performance: { now: () => now }, Math, console };
let now = 0;
win.performance = sandbox.performance;
const vm = require('vm');
vm.createContext(sandbox);
Object.assign(sandbox, { requestAnimationFrame: win.requestAnimationFrame, cancelAnimationFrame: win.cancelAnimationFrame });
vm.runInContext(src, sandbox);
const emit = (type, ev) => (listeners[type] || []).forEach(fn => fn(ev));
const frame = (ms) => { now += ms; if (rafCb) { const cb = rafCb; rafCb = null; cb(now); } };

if (!global.__reduce) {
  for (let i = 0; i < 120; i++) frame(16);
  emit('pointermove', { clientX: 400, clientY: 300 });
  for (let i = 0; i < 30; i++) { emit('pointermove', { clientX: 400 + i * 12, clientY: 300 + i * 5 }); frame(16); }
  emit('pointerdown', { clientX: 500, clientY: 400 });
  for (let i = 0; i < 300; i++) frame(16);
  emit('pointerout', { relatedTarget: null });
  for (let i = 0; i < 60; i++) frame(16);
  console.log('motion mode: 500+ frames OK; raf still scheduled:', !!rafCb);
} else {
  emit('pointermove', { clientX: 100, clientY: 700 });
  console.log('reduced mode: rafCb scheduled (expect false):', !!rafCb);
}
console.log('canvas calls sample:', Object.keys(calls).length, 'distinct methods; arc:', calls.arc, 'drawImage:', calls.drawImage);
EOF
